attempts.proposal:
SELECT ?instrumentationFunction ?assetIdentifier
WHERE {
  ?equipment a <https://example.org/aas/SMC> ;
             <https://example.org/dexpi/hasInstrumentationFunction> ?instrumentationFunction ;
             <https://example.org/dexpi/hasAssetIdentifier> ?assetIdentifier .
  FILTER (str(?instrumentationFunction) = "reactor temperature")
  FILTER (str(?assetIdentifier) = "https://aas.example.com/TI101")
}
LIMIT 100

